const items = [
  { topic: "ns=1;s=MotorSpeed", datatype: "Double", name: "Motor Speed" },
  { topic: "ns=1;s=Temperature", datatype: "Double", name: "Temperature" },
  { topic: "ns=1;s=Pressure", datatype: "Double", name: "Pressure" },
  { topic: "ns=1;s=Vibration", datatype: "Double", name: "Vibration" },
  { topic: "ns=1;s=Current", datatype: "Double", name: "Current" },
  { topic: "ns=1;s=ProductionCount", datatype: "UInt32", name: "Production" },
  { topic: "ns=1;s=MachineState", datatype: "String", name: "Machine State" },
  { topic: "ns=1;s=Quality", datatype: "Double", name: "Quality" }
];
return [items.map(item => ({
  topic: item.topic,
  datatype: item.datatype,
  browseName: item.name,
  payload: ""
}))];

let speed = msg.payload;
if (speed < 0 || speed > 3000) { return null; }
let speedPercent = (speed / 1500) * 100;
let anomaly = (speed < 500 || speed > 2500) ? 1 : 0;
msg.measurement = "motor";
msg.payload = [{ speed: speed, speed_percent: speedPercent, anomaly: anomaly }, { location: "line1", sensor: "speed_sensor" }];
return msg;

let temp = msg.payload;
let warning = temp > 75 ? 1 : 0;
let critical = temp > 85 ? 1 : 0;
if (critical) { node.warn("CRITIQUE : Température = " + temp + "°C"); }
msg.measurement = "temperature";
msg.payload = [{ value: temp, warning: warning, critical: critical }, { location: "line1", sensor: "temp_sensor" }];
return msg;

let pressure = msg.payload;
let history = context.get('pressure_history') || [];
history.push(pressure);
if (history.length > 5) { history.shift(); }
context.set('pressure_history', history);
let avg = history.reduce((a, b) => a + b, 0) / history.length;
msg.measurement = "pressure";
msg.payload = [{ value: pressure, average: avg, deviation: Math.abs(pressure - avg) }, { location: "line1", sensor: "pressure_sensor" }];
return msg;

let vibration = msg.payload;
let status_code = vibration < 0.6 ? 0 : (vibration < 0.8 ? 1 : 2);
if (status_code === 2) { node.error("VIBRATION CRITIQUE : " + vibration + " mm/s"); }
msg.measurement = "vibration";
msg.payload = [{ value: vibration, status_code: status_code }, { location: "line1", sensor: "vibration_sensor", status: ["Normal","Warning","Critical"][status_code] }];
return msg;

let current = msg.payload;
let power = Math.sqrt(3) * 400 * current * 0.85 / 1000;
msg.measurement = "electrical";
msg.payload = [{ current: current, power_kw: power, voltage: 400 }, { location: "line1", phase: "3ph" }];
return msg;

let count = msg.payload;
let lastCount = context.get('last_production_count') || count;
let lastTime = context.get('last_production_time') || Date.now();
let currentTime = Date.now();
let deltaCount = count - lastCount;
let deltaTime = (currentTime - lastTime) / 1000;
let rate = deltaTime > 0 ? (deltaCount / deltaTime) * 3600 : 0;
context.set('last_production_count', count);
context.set('last_production_time', currentTime);
msg.measurement = "production";
msg.payload = [{ total_count: count, rate_per_hour: rate, delta_count: deltaCount }, { location: "line1", line: "production_line_1" }];
return msg;

let state = msg.payload;
let stateCode = { Stopped:0, Starting:1, Running:2, Alarm:3 }[state] !== undefined ? { Stopped:0, Starting:1, Running:2, Alarm:3 }[state] : -1;
let lastState = context.get('last_state') || state;
let stateChanged = (lastState !== state) ? 1 : 0;
if (stateChanged) { node.warn("État changé : " + lastState + " → " + state); }
context.set('last_state', state);
msg.measurement = "machine_state";
msg.payload = [{ state_code: stateCode, state_changed: stateChanged }, { location: "line1", state: state }];
return msg;

let quality = msg.payload;
let history = context.get('quality_history') || [];
history.push(quality);
if (history.length > 10) { history.shift(); }
context.set('quality_history', history);
let avg = history.reduce((a, b) => a + b, 0) / history.length;
let variance = history.reduce((sum, val) => sum + Math.pow(val - avg, 2), 0) / history.length;
let stdDev = Math.sqrt(variance);
msg.measurement = "quality";
msg.payload = [{ value: quality, average: avg, std_deviation: stdDev, below_target: quality < 95 ? 1 : 0 }, { location: "line1", product: "product_a" }];
return msg;
